package ai.decisionos.aside;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;

/** Investor filming branch. Live tools report receipts; vision screens are labelled throughout. */
