 void expand(){full=!full;for(int n=0;n<root.getChildCount();n++){View v=root.getChildAt(n);if(v!=browserBox)v.setVisibility(full?View.GONE:View.VISIBLE);}resultScroll.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(140)));}
 void submit(){String s=input.getText().toString().trim();if(s.isEmpty())return;if(!requestId.isEmpty()){Toast.makeText(this,"Please wait for the current request.",0).show();return;}try{requestId=java.util.UUID.randomUUID().toString();JSONObject j=new JSONObject().put("id",requestId).put("task",s).put("scene",mode).put("createdAt",System.currentTimeMillis());write(new File(dir,"request.json"),j.toString());phase.setText("Qwen · Request received");answer.setText("Checking original sources in your browser.");send.setEnabled(false);input.clearFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);}catch(Exception e){requestId="";phase.setText("Could not save request");}}
 static void write(File f,String s)throws Exception{File temp=new File(f.getParentFile(),f.getName()+".tmp");try(FileOutputStream o=new FileOutputStream(temp)){o.write(s.getBytes(StandardCharsets.UTF_8));}if(!temp.renameTo(f))throw new IOException("rename failed");}
 final Runnable tick=new Runnable(){public void run(){if(destroyed)return;try{File f=new File(dir,"status.json");if(f.exists()&&!mode.equals("easy")&&!mode.equals("train")&&!mode.equals("family")&&!mode.equals("logo")){String s=new String(java.nio.file.Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);if(!s.equals(last)){last=s;JSONObject r=new JSONObject(s);if(r.optString("id").equals(requestId)){phase.setText(r.optString("phase","Qwen is working"));if(r.has("answer"))answer.setText(r.optString("answer"));if(r.optString("state").equals("completed")||r.optString("state").equals("failed")){requestId="";send.setEnabled(true);}}}}}catch(Exception ignored){}ui.postDelayed(this,400);}};
 void logs(){try{JSONObject r=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(dir,"status.json").toPath()),StandardCharsets.UTF_8));new AlertDialog.Builder(this).setTitle("Actual Qwen tool calls").setMessage(r.optString("log","No tool calls yet.")).setPositiveButton("Close",null).show();}catch(Exception e){Toast.makeText(this,"Run a request first.",0).show();}}
 void document(){File f=new File(dir,"application.docx");if(!f.isFile()){Toast.makeText(this,"No document has been created yet.",0).show();return;}try(InputStream in=new FileInputStream(f)){String s=CompanionDocumentPreview.read(in);ScrollView view=new ScrollView(this);TextView t=text(s,17,ink,false);t.setPadding(dp(20),dp(20),dp(20),dp(20));view.addView(t);new AlertDialog.Builder(this).setTitle("DOCX · Generated file").setView(view).setPositiveButton("Close",null).show();}catch(Exception e){Toast.makeText(this,"Could not read document",0).show();}}
 void scenes(){String[] labels={"Live · Scholarship notice","Live · Email and document","Vision · Easy to use","Vision · Train guidance","Vision · Family sharing","Nubi logo"};String[] modes={"school","mail","easy","train","family","logo"};new AlertDialog.Builder(this).setTitle("Demo scenes").setItems(labels,(d,n)->{startActivity(new Intent(this,InvestorDemoActivity.class).putExtra("scene",modes[n]));finish();}).show();}
 void vision(){if(mode.equals("logo")){root.setGravity(Gravity.CENTER);add(root,text("nubi.",72,0xff19b38b,true),-2);add(root,text("AI should work\nfor everyone.",30,ink,true),-2);add(root,text("AI for the Real World",16,0xff82928d,false),-2);return;}TextView label=text("PRODUCT VISION · Concept preview",12,purple,true);add(root,label,-2);body=col(8);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 if(mode.equals("family")){add(body,text("A little help.\nFor every generation.",34,ink,true),-2);add(body,text("From your campus life\nto your family’s everyday moments.",20,0xff7e8c8e,false),-2);for(String s:new String[]{"Me · Classes and assignments","Parents · Everyday benefits","Grandma · Clear, simple guidance"}){TextView card=text(s,22,ink,true);card.setPadding(dp(18),dp(28),dp(18),dp(28));card.setBackground(bg(0xffe9f7f1,24));add(body,card,-2);}add(body,button("Introduce Nubi to my family",()->{Intent share=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"Nubi — AI should work for everyone. From campus life to family life. (Product vision)");startActivity(Intent.createChooser(share,"Share Nubi"));}),60);return;}
 add(body,text("How can I\nhelp you today?",38,ink,true),-2);add(body,text("Skip the complicated apps.\nJust ask Nubi.",21,0xff7e8c8e,false),-2);Button mic=button("●  Tap to speak",()->{try{Intent i=new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE,"en-US");startActivityForResult(i,801);}catch(Exception e){Toast.makeText(this,"Speech recognition is unavailable. Try the example request.",0).show();}});mic.setTextSize(24);add(body,mic,120);add(body,button(mode.equals("train")?"Try it · Where do I board?":"Try it · I’d like a burger",()->visionResult(mode.equals("train")?"Where do I board my train?":"I’d like a burger")),65);add(body,text("The microphone uses your device’s speech recognition.\nExamples show a product vision, not live discounts or platform information.",13,0xff7e8c8e,false),-2);
 }
 void visionResult(String heard){body.removeAllViews();add(body,text("“"+heard+"”",28,ink,true),-2);if(mode.equals("train")){add(body,text("Let’s check your ticket",34,ink,true),-2);add(body,text("We’ll check your destination and time,\nthen match the station departure board.",23,0xff647b7c,false),-2);add(body,text("1. Check your ticket\n2. Match the departure board\n3. Get clear boarding guidance",24,ink,true),-2);add(body,text("Product vision · No live platform has been checked.",14,purple,true),-2);}else{add(body,text("Nubi finds the benefits.\nYou order as usual.",32,ink,true),-2);TextView card=text("Find in-store benefits\n\nCheck the official app’s coupon terms,\nthen use it at the counter or kiosk.\n\nPayment options depend on\nthe store and coupon conditions.",23,ink,false);card.setPadding(dp(20),dp(24),dp(20),dp(24));card.setBackground(bg(0xffe5f6ed,24));add(body,card,-2);add(body,button("How to use it in store",()->new AlertDialog.Builder(this).setTitle("Order the way you usually do").setMessage("1. Check terms in the official app\n2. Show the coupon at the counter or kiosk\n3. Pay using the store’s available methods\n\nProduct vision. No coupon was issued and no order was placed.").setPositiveButton("Got it",null).show()),64);add(body,text("Product vision · No coupon, discount or barcode has been issued.",13,purple,true),-2);}}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==801&&c==RESULT_OK&&data!=null){java.util.ArrayList<String> list=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(list!=null&&!list.isEmpty())visionResult(list.get(0));}}
 @Override protected void onPause(){WebSessionPolicy.checkpoint();super.onPause();}
 @Override protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);if(web!=null)web.destroy();super.onDestroy();}
